const fruits = ["яблоко", "банан", "груша"];
//  индекс:       0         1        2
console.log(fruits[0]); // яблоко
console.log(fruits[1]); // банан

const fruits = ["яблоко", "банан", "груша"];
fruits.push("киви");
// ["яблоко", "банан", "груша", "киви"] — length 4
fruits.pop();
// ["яблоко", "банан", "груша"] — length 3

fruits.forEach((fruit, index) => {
  console.log(index, fruit);
});
// 0 яблоко
// 1 банан
// 2 груша

const prices = [1000, 2500, 500];
const salePrices = prices.map((price) => price * 0.9);

console.log(prices);     // [1000, 2500, 500]
console.log(salePrices); // [900, 2250, 450]

function isEven(number) {
  return number % 2 === 0;
}

const numbers = [1, 2, 3, 4, 5, 6];
const evens = numbers.filter((n) => isEven(n));
console.log(evens); // [2, 4, 6]

const products = [
  { name: "Телефон", price: 3000 },
  { name: "Наушники", price: 800 },
];
const found = products.find((p) => p.name === "Наушники");
console.log(found.price); // 800

const prices = [500, 1200, 300, 2500, 800, 1500];
let total = 0;
for (const price of prices) {
  total = total + price;
}
console.log(`Итого: ${total}`); // Итого: 6800

